const beforeExport = (event: ExcelBeforeExportEvent<Employee>) => {
  // Modify columns before export
  event.columns = event.columns.filter(col => col.field !== 'salary');
  // Modify data before export
  event.dataSource = event.dataSource.filter(emp => emp.status === 'Active');
  // Cancel export if needed
  if (event.dataSource.length === 0) {
    event.cancel = true;
  }
};
