  // Transform data
  event.dataSource = event.dataSource.map(row => ({
    ...row,
    name: row.name.toUpperCase()
  }));

  // Cancel if needed
  if (event.dataSource.length === 0) {
    event.cancel = true;
  }
};

const config: PdfExportSettings = {
  onBeforePdfExport: handleBeforePdfExport
};
